<?php /** @var ?array<string,mixed> $row */ use Vertex\Services\Integrations;
$v = static fn (string $k, string $d = ''): string => old($k, $row !== null ? (string) ($row[$k] ?? $d) : $d); ?>
<div class="page-head"><div><p class="eyebrow">Integrations register</p><h1><?= $row ? e($row['name']) : 'Add a service' ?></h1></div><a class="btn btn-ghost" href="/admin/compliance/integrations">&larr; All services</a></div>
<div class="panel"><form method="post" action="/admin/compliance/integrations/<?= $row ? e($row['id']) : 'new' ?>" class="form-grid" novalidate><?= csrf_field() ?>
    <div class="field"><label for="i-name">Name</label><input id="i-name" name="name" required maxlength="120" value="<?= e($v('name')) ?>"></div>
    <div class="field"><label for="i-cat">Category</label><select id="i-cat" name="category"><?php foreach (Integrations::CATEGORIES as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('category', 'other') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="i-state">State</label><select id="i-state" name="state"><?php foreach (Integrations::STATES as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('state', 'planned') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select>
        <p class="hint">"In use today" must be true. A service that is only a possibility is shown on the public page as <strong>not in use</strong>.</p></div>
    <div class="field"><label class="check"><input type="checkbox" name="show_public" value="1"<?= $row === null || (int) ($row['show_public'] ?? 1) === 1 ? ' checked' : '' ?>> Show on the public Third-Party Services page</label></div>
    <div class="field"><label for="i-purpose">What it does for us</label><textarea id="i-purpose" name="purpose" rows="3" maxlength="2000"><?= e($v('purpose')) ?></textarea></div>
    <div class="field"><label for="i-data">Data categories involved</label><textarea id="i-data" name="data_shared" rows="3" maxlength="2000"><?= e($v('data_shared')) ?></textarea></div>
    <div class="field"><label for="i-loc">Where data is processed (optional)</label><input id="i-loc" name="location_note" maxlength="255" value="<?= e($v('location_note')) ?>"></div>
    <div class="field"><label for="i-url">Provider website (https://)</label><input id="i-url" name="provider_url" type="url" maxlength="255" value="<?= e($v('provider_url')) ?>"></div>
    <div class="field"><label for="i-priv">Provider privacy policy (https://)</label><input id="i-priv" name="privacy_url" type="url" maxlength="255" value="<?= e($v('privacy_url')) ?>"></div>
    <div class="field"><label for="i-link">Where its real technical settings are (optional)</label><input id="i-link" name="settings_link" maxlength="120" value="<?= e($v('settings_link')) ?>" placeholder="/admin/settings#razorpay"><p class="hint">Passwords and API keys never go in this register.</p></div>
    <div class="field"><label for="i-cc">Cookies or browser storage</label><select id="i-cc" name="cookie_category"><?php foreach (Integrations::COOKIE_CATEGORIES as $c => $l) : ?><option value="<?= e($c) ?>"<?= $v('cookie_category', 'none') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="i-cd">Cookies it sets (one per line: name | purpose | how long)</label><textarea id="i-cd" name="cookie_details" rows="3" maxlength="2000"><?= e($v('cookie_details')) ?></textarea></div>
    <div class="field"><label for="i-sc">Script to load after consent (https://, optional categories only)</label><input id="i-sc" name="script_url" type="url" maxlength="255" value="<?= e($v('script_url')) ?>"><p class="hint">Loaded in the visitor's browser only after they allow the category above. Its host is added to the site's Content Security Policy only while this service is "in use today".</p></div>
    <div class="form-actions"><button class="btn btn-primary" type="submit">Save</button></div></form></div>
